SCHEMA_CONTEXT = """PostgreSQL analytics schema. Read only. Base tables: dealers(dealer_id int, dealer_name text, dealer_type text, region text, district text, credit_limit numeric); products(product_id int, product_name text, category text, target_crop text, pack_size text, mrp numeric, dealer_price numeric, shelf_life_months int); sales_orders(order_id int, order_date date, dealer_id int, product_id int, quantity int, unit_price numeric, discount_pct numeric, total_amount numeric, dispatch_date date, payment_status text); payments(payment_id int, order_id int, amount_received numeric, payment_date date, payment_mode text); crop_calendar(crop text, region text, sowing_month int, peak_demand_month int); inventory(inventory_id int,product_id int,batch_no text,mfg_date date,expiry_date date,quantity_available numeric,reorder_level numeric). Views: monthly_sales_summary(month,region,total_revenue,total_orders,avg_order_value); dealer_scorecard(dealer_id,dealer_name,region,total_revenue,order_count,credit_limit,current_outstanding,credit_utilization_pct); dealer_aging_report(dealer_id,dealer_name,outstanding_0_30,outstanding_31_60,outstanding_61_90,outstanding_90_plus); product_crop_performance(product_id,product_name,target_crop,total_revenue,total_quantity_sold,rank_within_crop_category); inventory_status(product_id,product_name,quantity_available,reorder_level,is_below_reorder,days_to_expiry); regional_performance(region,total_revenue,dealer_count,avg_revenue_per_dealer); demand_forecast_results(product_id,model_used,mape,rmse,forecast_month,predicted_qty,actual_qty); dealer_segments(dealer_id,recency,frequency,monetary,cluster_id,segment_label)."""
